source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    sep_colors = {grid[r][0] for r in sep_rows}
    sep_colors |= {grid[0][c] for c in sep_cols}
    colors = {v for row in grid for v in row if v != 0 and v not in sep_colors}

    def points(color, rs, cs):
        r0, r1 = rs
        c0, c1 = cs
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] == color}

    for color in colors:
        pair_counts = {}
        for ri, rs in enumerate(row_spans):
            for ci in range(len(col_spans) - 1):
                left = points(color, rs, col_spans[ci])
                right = points(color, rs, col_spans[ci + 1])
                width = col_spans[ci][1] - col_spans[ci][0]
                if left and right and len(left) == len(right):
                    reflected = {(r, width - 1 - c) for r, c in left}
                    if reflected == right:
                        pair_counts[(ci, ci + 1)] = pair_counts.get((ci, ci + 1), 0) + 1
        if not pair_counts:
            continue
        pair = max(pair_counts, key=pair_counts.get)
        for rs in row_spans:
            left = points(color, rs, col_spans[pair[0]])
            right = points(color, rs, col_spans[pair[1]])
            if bool(left) == bool(right):
                continue
            source_col, dest_col = (pair[0], pair[1]) if left else (pair[1], pair[0])
            source_span, dest_span = col_spans[source_col], col_spans[dest_col]
            width = source_span[1] - source_span[0]
            r0 = rs[0]
            for rr, cc in (left if left else right):
                dr = r0 + rr
                dc = dest_span[0] + width - 1 - cc
                if 0 <= dr < h and 0 <= dc < w and out[dr][dc] == 0:
                    out[dr][dc] = color
    return out
'''
